   162	    StaticNativeApp(Method m, Applicable defn) {
   163	        this.m = m;
   164	        this.ps = m.getParameterTypes();
   165	        this.result = declaredResult(defn);
   166	        int at = -1, i = 0;
   167	        for (Param p : NodeUtil.getParams(defn)) { if (p.getName().getText().equals("self")) at = i; i++; }
   168	        this.selfAt = at;
   169	    }
