   194	    private FValue call(List<FValue> args) {
   195	        if (args.size() != ps.length) return error("Native " + m + " given " + args.size() + " arguments");
   196	        Object[] xs = new Object[ps.length];
   197	        for (int i = 0; i < ps.length; i++) xs[i] = unbox(ps[i], args.get(i));
   198	        try {
   199	            return box(m.getReturnType(), result, m.invoke(null, xs));
   200	        }

200	        }
201	        catch (InvocationTargetException e) {
202	            Throwable t = e.getCause();
203	            FortressError f = raised(t);
204	            if (f != null) throw f;
205	            if (t instanceof RuntimeException) throw (RuntimeException) t;
206	            if (t instanceof Error) throw (Error) t;
207	            return error(t.toString());
208	        }
209	        catch (IllegalAccessException e) {
210	            return error(e.toString());
211	        }
212	    }
