168	    /** declarer: the type that declares the method, whose value is self, or null for a function. */
169	    public static Applicable checkAndLoadNative(Applicable defn, boolean isFunctionalMethod,
170	                                                com.sun.fortress.interpreter.evaluator.types.FType declarer) {
171	        Option<Expr> optBody = NodeUtil.getBody(defn);
172	        if (optBody.isNone()) return defn;
173	        Expr body = optBody.unwrap();
174	        Expr fn;
175	        Expr arg;
176	        if (body instanceof Juxt && ((Juxt) body).isTight()) {
177	            List<Expr> juxts = ((Juxt) body).getExprs();
178	            if (juxts.size() != 2) return defn;
179	            fn = juxts.get(0);
180	            arg = juxts.get(1);
181	        } else if (body instanceof MathPrimary) {
182	            MathPrimary mp = (MathPrimary) body;
183	            List<MathItem> args = mp.getRest();
184	            if (args.size() != 1) return defn;
185	            fn = mp.getFront();
186	            MathItem mi = args.get(0);
187	            if (mi instanceof ExprMI) arg = ((ExprMI) mi).getExpr();
188	            else return defn;
189	        } else // (!(body instanceof TightJuxt || body instanceof MathPrimary))
190	            return defn;
191	        if (!(fn instanceof VarRef)) return defn;
192	        if (!(arg instanceof StringLiteralExpr)) return defn;
193	        Id name = ((VarRef) fn).getVarId();
194	        if (!name.getText().equals("builtinPrimitive")) return defn;
195	        String str = ((StringLiteralExpr) arg).getText();
196	        Pair<String, Applicable> key = new Pair<String, Applicable>(str, defn);
197	        synchronized (cache) {
198	            NativeApp res = cache.get(key);
199	            if (res != null) return res;
200	            if (StaticNativeApp.isHelperString(str)) {
201	                Object found = StaticNativeApp.find(str, defn, declarer == null ? null : declarer.getName());
202	                if (found instanceof String) return bug(defn, (String) found);
203	                res = new StaticNativeApp((java.lang.reflect.Method) found, defn);
204	                res.init(defn, isFunctionalMethod);
205	                cache.put(key, res);
206	                return res;
207	            }
208	            try {
209	                // System.err.println("Loading primitive class "+str);
210	                Class nativeAct = Class.forName(str);
211	                res = (NativeApp) nativeAct.newInstance();
212	                res.init(defn, isFunctionalMethod);
213	                cache.put(key, res);
214	                return res;
215	            }
216	            catch (java.lang.ClassNotFoundException x) {
217	                return bug(defn, "Native class " + str + " not found.", x);
218	            }
219	            catch (java.lang.InstantiationException x) {
220	                return bug(defn, "Native class " + str + " has no nullary constructor.", x);
221	            }
222	            catch (java.lang.IllegalAccessException x) {
223	                return bug(defn, "Native class " + str + " cannot be accessed.", x);
224	            }
225	            catch (java.lang.ClassCastException x) {
226	                return bug(defn, "Native class " + str + " is not a NativeApp.", x);
227	            }
228	        }
229	    }
